create table xxventuri.xxeba_tally_receivables_t (
    batch_number       number,
    customer_id        varchar2(250 byte),
    pending_amount     varchar2(250 byte),
    currency           varchar2(20 byte),
    created_by         varchar2(255 byte),
    created_date       timestamp(6),
    updated_by         varchar2(255 byte),
    updated_date       timestamp(6),
    status             varchar2(10 byte),
    invoice_number     varchar2(22 byte),
    invoice_date       timestamp(6),
    inv_pending_amount varchar2(255 byte),
    lastpaymt_recdate  timestamp(6)
);


